<script>
let activityPage=1;
async function loadActivities(reset){if(reset){activityPage=1;document.getElementById('activityList').innerHTML='';}const q=document.getElementById('activitySearch').value;const f=document.getElementById('activityFilter').value;const u='{{ route('bm.activities') }}?page='+activityPage+'&limit=10&filter='+encodeURIComponent(f)+'&q='+encodeURIComponent(q);const r=await fetch(u);const d=await r.json();if(!d.success)return;const box=document.getElementById('activityList');d.items.forEach(function(a){box.insertAdjacentHTML('beforeend','<div class="activity-row"><div class="activity-icon">'+esc(a.type).charAt(0)+'</div><div><strong>'+esc(a.client_name)+'</strong><small>'+esc(a.type)+' · '+esc(a.officer)+' · '+new Date(a.date).toLocaleString()+'</small></div><b>₦'+Number(a.amount).toLocaleString()+'</b></div>');});document.getElementById('loadMore').style.display=d.has_more?'block':'none';if(d.has_more)activityPage++;}
function esc(s){return String(s||'').replace(/[&<>"']/g,function(m){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m];});}
document.getElementById('loadMore').onclick=function(){loadActivities(false)};document.getElementById('activityFilter').onchange=function(){loadActivities(true)};let timer;document.getElementById('activitySearch').oninput=function(){clearTimeout(timer);timer=setTimeout(function(){loadActivities(true)},300)};
async function markRead(){await fetch('{{ route('bm.notifications.read') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'}});document.getElementById('notifications').innerHTML='<div class="empty">No unread notifications.</div>';}
</script>
